INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12635, 94180, 'tt1674098', NULL, 'Pájaros volando', 'Pájaros volando', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/ptGAsnFcZDF186SusDtY2wjqpR5.jpg', NULL, 'José (Diego Capusotto) lives in Buenos Aires with his father, with whom he doesn''t have a good relationship. He''s a musician, but supports himself with the earnings from his taxi company, and when he can, he plays with his band in pubs. He''s nostalgic for the success he could never achieve again, like when he played with his cousin Miguel (Luis Luque). They had both achieved a certain notoriety with the song "Pájaros vuela" (Flying Birds) by their band "Dientes de Limón." After a long time without seeing each other, Miguel, who lives in Las Pircas, a small town in the mountains of Córdoba, comes to visit him and suggests that he leave the city and come with him.', NULL, NULL, 0.5989, 5.3, 0, 1.01, '2026-08-30 03:38:43', '2026-08-30 03:38:43');
