INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12680, 14736, 'tt0199725', NULL, 'Love & Basketball', 'Love & Basketball', 'movie', 2000, 'https://image.tmdb.org/t/p/w500/zNZWNX19FZ5QyedprVM0ldsXFiP.jpg', 'https://image.tmdb.org/t/p/original/jF71CkY9bHyWvZTNQUThyzecXYb.jpg', 'Monica Wright and Quincy McCall grew up in the same neighborhood and have known each other since childhood. As they grow into adulthood, they fall in love, but they also share another all-consuming passion: basketball.  As Quincy and Monica struggle to make their relationship work, they follow separate career paths though high school and college basketball and, they hope, into stardom in big-league professional ball.', NULL, NULL, 2.5212, 7.353, 0, 10.02, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12681, 13279, 'tt0947802', NULL, 'Lakeview Terrace', 'Lakeview Terrace', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/A1kqp2hALf8Gd03vDACnR0EtFWo.jpg', 'https://image.tmdb.org/t/p/original/6WfnLguRcpYQlJ6Wkx5CO7c8LpV.jpg', 'A young interracial couple has just moved into their California dream home when they become the target of their next-door neighbor, who disapproves of their relationship. A tightly wound LAPD officer has appointed himself the watchdog of the neighborhood. His nightly foot patrols and overly watchful eyes bring comfort to some, but he becomes increasingly aggressive to the newlyweds. These persistent intrusions into their lives cause the couple to fight back.', NULL, NULL, 5.0562, 5.967, 0, 9.53, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12682, 479, 'tt0162650', NULL, 'Shaft', 'Shaft', 'movie', 2000, 'https://image.tmdb.org/t/p/w500/5ncvnNPaN73cOqD4muE413sSOyY.jpg', 'https://image.tmdb.org/t/p/original/sblTwYXpm6Nrl4qewg3526lBdlK.jpg', 'New York police detective John Shaft arrests Walter Wade Jr. for a racially motivated slaying. But the only eyewitness disappears, and Wade jumps bail for Switzerland. Two years later Wade returns to face trial, confident his money and influence will get him acquitted -- especially since he''s paid a drug kingpin to kill the witness.', NULL, NULL, 6.834, 6.021, 0, 9.53, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12683, 686548, 'tt2235372', NULL, 'Son of the South', 'Son of the South', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/3LExC6FEHKkHdeb7z3W0ncU2CKY.jpg', 'https://image.tmdb.org/t/p/original/s3tlKP2rFbFpLrviwWd7PIRpsfO.jpg', 'In civil rights era Montgomery, Alabama, Klansman''s grandson Bob Zellner must choose which side of history to be on during the Movement. Defying his family and white Southern norms, he fought against social injustice, repression and violence to change the world around him', NULL, NULL, 2.5199, 6.494, 0, 9.52, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
