INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12685, 508791, 'tt6423362', NULL, 'The Sun Is Also a Star', 'The Sun Is Also a Star', 'movie', 2019, 'https://image.tmdb.org/t/p/w500/dGl7ZnnL3WoiCKQAQdgkEF0EAbj.jpg', 'https://image.tmdb.org/t/p/original/3CFuFIwtSSQU4Fyd5NnmHnNZq9w.jpg', 'Two young New Yorkers begin to fall in love over the course of a single day, as a series of potentially life-altering meetings loom over their heads - hers concerning her family’s deportation to Jamaica, and his concerning an education at Dartmouth.', NULL, NULL, 4.7851, 6.94, 0, 9.52, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12686, 15363, 'tt0437777', NULL, 'Something New', 'Something New', 'movie', 2006, 'https://image.tmdb.org/t/p/w500/lcwB60GqQaWUgUw1CCE5gm5XHI1.jpg', 'https://image.tmdb.org/t/p/original/z3rXaWnmQTJJw9ioNxRQ23rYXHw.jpg', 'Kenya McQueen thought she had it all: a successful career, good friends and family. There was just one thing she didn''t have under control: her love life. All that changes when she meets sexy, free-spirited Brian Kelly. But when her ideal man arrives on the scene, Kenya must decide between the relationship everyone expects and the romance no one expected.', NULL, NULL, 4.3741, 6.445, 0, 10.05, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12687, 339419, 'tt4669986', NULL, 'Loving', 'Loving', 'movie', 2016, 'https://image.tmdb.org/t/p/w500/teNPeDIRGWxtvMaJsNa7lw5IgiL.jpg', 'https://image.tmdb.org/t/p/original/zjvX2vJmm3f25JujVEp5DEu2eKi.jpg', 'In 1958, in the state of Virginia, the idea of interracial marriage was not only considered to be immoral to many, it was also illegal. When Richard and Mildred fall in love, they are aware of the eyes staring at them and the words said behind their backs. It''s when they get married, however, that words and looks become actions, and the two are arrested. The couple decide to take their case all of the way to the Supreme Court in order to fight for their love. Based on a true story.', NULL, NULL, 3.6654, 6.7, 0, 10.05, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12688, 14299, 'tt1042877', NULL, 'Cadillac Records', 'Cadillac Records', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/u2GtllItFwaXMLj4uCeKYt9wf4l.jpg', 'https://image.tmdb.org/t/p/original/ubgl0v0crnOGYPGkR2hhIwv7Chm.jpg', 'The story of sex, violence, race and rock and roll in 1950s Chicago, and the exciting but turbulent lives of some of America''s musical legends, including Muddy Waters, Leonard Chess, Little Walter, Howlin'' Wolf, Etta James and Chuck Berry.', NULL, NULL, 4.3263, 7.075, 0, 10.05, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12689, 264940, 'tt0049253', NULL, 'Corinna Darling', 'Geliebte Corinna', 'movie', 1956, 'https://image.tmdb.org/t/p/w500/sk9k8qhQJboqWApCJTWtdvyT6kt.jpg', NULL, 'Out of love, young Corinna follows the plantation owner Mannsfeld to the Far East - where she has to realize that he is already married. A small consolation for her is the fact that Mannsfeld is not about a womanizer, but that he is serious about his love for Corinna. The only thing standing in the way of this love is his wife, who, despite the broken marriage, does not want to let Mannsfeld go. When the wife is murdered, this crime seems to bring dubious happiness to the two of them - but it doesn''t last long.', NULL, NULL, 0.8005, 6.7, 0, 11.125, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
