INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12691, 17915, 'tt0120576', NULL, 'Dance with Me', 'Dance with Me', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/zNUxfWLFGfM7IC7LpxZqWRCnVMK.jpg', 'https://image.tmdb.org/t/p/original/hZlrvm9wIRuHLXdN73XcFkznkWZ.jpg', 'Young Cuban Rafael just buried his mother, and comes to Houston to meet his father John for the first time. The difficult part is that John doesn''t know he is Rafael''s father. John runs a dance studio, and everyone prepares for the World Open Dance championship in Las Vegas. It soon becomes clear Rafael is a very good dancer, and Ruby is the biggest hope for the studio at the championship.', NULL, NULL, 3.2933, 6.901, 0, 9.52, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
