INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12693, 741335, 'tt13064272', NULL, 'Sing a Bit of Harmony', 'アイの歌声を聴かせて', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/fKUsPOcpFQpdZYsmro4bVAonp93.jpg', 'https://image.tmdb.org/t/p/original/2hkyfxdJkBRR75msNs6V7Y9hd8k.jpg', 'Satomi is fine being alone until an AI named Shion joins her class with a song and a promise to make her happy. While Shion’s musical numbers and princess gowns don’t quite pass as human, her antics bring Satomi closer to four other classmates. Together, they make memories worth saving, but even our most precious data can be erased.', NULL, NULL, 2.4602, 7.4, 0, 5.02, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
