INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12706, 1341138, 'tt33305867', NULL, 'Spa Weekend', 'Spa Weekend', 'movie', 2026, 'https://image.tmdb.org/t/p/w500/7LIP05jWWwLPObSOAVbX7xkWPQ0.jpg', 'https://image.tmdb.org/t/p/original/ftFf9sfJq69xJ0AuiaIuDKBtfzg.jpg', 'Four lifelong friends realize that somewhere between careers, relationships, families, and everyday responsibilities, they’ve forgotten how to take care of themselves and each other. Burned out and overdue for a break, the women escape to a luxury spa retreat for an unforgettable weekend dedicated to fun, laughter, and a lot of really bad decisions.', NULL, NULL, 21.8509, 6.5, 0, 1.45, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12707, 37726, 'tt0240119', NULL, 'Tomie', '富江', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/zfHdSceORPkzKUs7sjUQPK8dcov.jpg', 'https://image.tmdb.org/t/p/original/sSxuuzANk6Zo1fOWf9qWmWa7T57.jpg', 'Following some trauma in her past that has since been repressed, a young woman is trying to recover her memories with the help of a psychiatrist. During her hypnosis sessions, she repeats the name "Tomie" but is unable to recall where she knows it from. Meanwhile, a police detective is investigating a string of brutal murders, where he also runs across the name "Tomie." How are the two connected?', NULL, NULL, 1.8028, 5.375, 0, 7.52, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12708, 870096, 'tt16118262', NULL, 'Restart the Earth', '重启地球', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/kl80N1g69v9QXe1wvkFza31WhD4.jpg', 'https://image.tmdb.org/t/p/original/rBXrCUya6Xj5wJeGAVXzHdMPNXH.jpg', 'When a drug to replicate plant cells creates a sentient form of flower, the planet is over taken by flora and humankind is depleted. A Chinese task force, a widowed father and his young daughter fight to survive in a mission to inject an antidote to the core of the plants to reverse their growth.', NULL, NULL, 2.9809, 6.7, 0, 1.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12709, 82700, 'tt1815862', NULL, 'After Earth', 'After Earth', 'movie', 2013, 'https://image.tmdb.org/t/p/w500/iXMvYIlzzJBs352CfeiQcBvovZt.jpg', 'https://image.tmdb.org/t/p/original/e3posvSzYf9PjrQg27W64Kyc8qq.jpg', 'One thousand years after cataclysmic events forced humanity''s escape from Earth, Nova Prime has become mankind''s new home. Legendary General Cypher Raige returns from an extended tour of duty to his estranged family, ready to be a father to his 13-year-old son, Kitai. When an asteroid storm damages Cypher and Kitai''s craft, they crash-land on a now unfamiliar and dangerous Earth. As his father lies dying in the cockpit, Kitai must trek across the hostile terrain to recover their rescue beacon. His whole life, Kitai has wanted nothing more than to be a soldier like his father. Today, he gets his chance.', NULL, NULL, 7.7483, 5.18, 0, 1.02, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12710, 399894, 'tt3007132', NULL, 'Daylight''s End', 'Daylight''s End', 'movie', 2016, 'https://image.tmdb.org/t/p/w500/sNDodM6si97uhiPhf5dTM6n6aDj.jpg', 'https://image.tmdb.org/t/p/original/Aiwk4Ywd296AkKeVtC2auwFKhyy.jpg', 'Years after a mysterious plague has devastated the planet and turned most of humanity into blood-hungry creatures, a rogue drifter on a vengeful hunt stumbles across a band of survivors in an abandoned police station and reluctantly agrees to try to help them defend themselves and escape to the sanctuary they so desperately need.', NULL, NULL, 4.0407, 5.813, 0, 1.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12711, 970947, 'tt20212786', NULL, 'The Shrouds', 'The Shrouds', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/xXoueIHdllGo5m0ChKvSATJYWBw.jpg', 'https://image.tmdb.org/t/p/original/kpzMKQyKbtaxf9OpJo0fiosSCMK.jpg', 'Inconsolable since the death of his wife, prominent businessman Karsh Relikh invents a revolutionary and controversial technology that enables the living to monitor their dear departed in their shrouds. One night, multiple graves, including that of Karsh’s wife, are desecrated, and he sets out to track down the perpetrators.', NULL, NULL, 5.9217, 5.826, 0, 8.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12712, 468735, 'tt6101602', NULL, 'Madeline''s Madeline', 'Madeline''s Madeline', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/8PcvYO5SHmPUFzdXpI2kzj3JtXN.jpg', 'https://image.tmdb.org/t/p/original/y00OqbAb2AZMz8JM19vmjjCN1KU.jpg', 'Madeline has become an integral part of a prestigious physical theater troupe. When the workshop''s ambitious director pushes the teenager to weave her rich interior world and troubled history with her mother into their collective art, the lines between performance and reality begin to blur. The resulting battle between imagination and appropriation rips out of the rehearsal space and through all three women''s lives.', NULL, NULL, 2.017, 5.945, 0, 8.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12713, 473706, 'tt6190348', NULL, 'Pin Cushion', 'Pin Cushion', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/947q315H51BBXJdyLRWqiLXSYhI.jpg', 'https://image.tmdb.org/t/p/original/kUMRSilcBvag2Ghie7PYlQ32bwo.jpg', 'Super close mother Lyn and daughter Iona (Dafty One and Dafty Two) are excited for their new life in a new town. Determined to make a success of things after a tricky start, Iona becomes ''best friends'' with Keely, Stacey and Chelsea. Used to being Iona''s bestie herself, Lyn feels left out. So Lyn also makes friends with Belinda, her neighbour.', NULL, NULL, 1.4653, 6.431, 0, 1.03, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12714, 2967, 'tt0416435', NULL, 'Unfabulous', 'Unfabulous', 'tv', 2004, 'https://image.tmdb.org/t/p/w500/oOqzMXvwAwIHGELwGP0HZB56AQy.jpg', 'https://image.tmdb.org/t/p/original/3TvJico2kyNq64MQlWjqx3jWDnJ.jpg', 'Unfabulous is an American children''s television series that aired on Nickelodeon. The series is about an "unfabulous" 7th Grade middle school student named Addie Singer, played by Emma Roberts. The show, which debuted in late summer 2004, was one of the most-watched programs in the United States among children between the age of 10 and 16 and was created by Sue Rose, who previously created the animated series Pepper Ann and Angela Anaconda.', NULL, NULL, 6.3279, 7.0, 0, 1.1, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12715, 390592, 'tt4211044', NULL, 'Adult Life Skills', 'Adult Life Skills', 'movie', 2016, 'https://image.tmdb.org/t/p/w500/1XiqACmd8cNOtD0pjxBoS7kWnGH.jpg', 'https://image.tmdb.org/t/p/original/e0GXVVzZgkdBAuiyAwzz1rsMrqg.jpg', 'Anna is stuck: she’s approaching 30 and has just moved back to her rural home-town, and into a shed in her mother’s backyard. She spends her time working a menial job at a local boating center and hides in the depths of her imagination, making movies with her thumbs. Irritated by her childish behavior, Anna''s mother insists that she move out of her shed and on with her life. When a troubled young boy starts hanging around, the two form an unlikely bond. Through their strange yet mutually beneficial friendship, Anna slowly begins to confront her perpetual state of arrested development.', NULL, NULL, 1.9407, 6.247, 0, 1.03, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
