INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12717, 11316, 'tt0067372', NULL, 'Macbeth', 'Macbeth', 'movie', 1971, 'https://image.tmdb.org/t/p/w500/35wNrDYuZjVCLurOmTZ5j490iuR.jpg', 'https://image.tmdb.org/t/p/original/isyOwiSRyLRFXdsMn0UiA7mQbXV.jpg', 'Scotland, 11th century. Driven by the twisted prophecy of three witches and the ruthless ambition of his wife, warlord Macbeth, bold and brave, but also weak and hesitant, betrays his good king and his brothers in arms and sinks into the bloody mud of a path with no return, sown with crime and suspicion.', NULL, NULL, 2.583, 7.1, 0, 9.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12718, 37376, 'tt0291118', NULL, 'The Cube', 'The Cube', 'movie', 1969, 'https://image.tmdb.org/t/p/w500/qVW4i5ZKJ9uZ3aLeCb1l3QCfntp.jpg', 'https://image.tmdb.org/t/p/original/yZtQoLqdL8OklZIJKdXeIeZYif7.jpg', 'An unnamed character is trapped in a cubical white room where others can enter and leave, but which he himself apparently cannot leave. A stool is brought in covered in strawberry jam, the furniture changes throughout the play. The main character is subjected to an increasingly puzzling and frustrating series of encounters, as a variety of people come through various hidden doors. But, as many remind him, he can only leave through his own door, so he must find it.', NULL, NULL, 1.7606, 7.1, 0, 10.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12719, 716703, 'tt9264728', NULL, 'What Lies Below', 'What Lies Below', 'movie', 2020, 'https://image.tmdb.org/t/p/w500/25FaS1xPTz1reG95D1M68Gc7NNG.jpg', 'https://image.tmdb.org/t/p/original/qLL6H9SGEwRRW6PJHixyUtbBjBE.jpg', 'A socially awkward teenager is blindsided when her mother introduces her to her new fiancée. At first, his charm, intelligence, and beauty seem too good to be true, and after a series of strange occurrences, the teenage daughter realizes that this new member of their family is not exactly who he seems.', NULL, NULL, 2.2983, 5.281, 0, 8.51, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
