INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12722, 8359, 'tt0846308', NULL, 'Kit Kittredge: An American Girl', 'Kit Kittredge: An American Girl', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/niHi0hJSryO5DpSVNCMASc3EELc.jpg', 'https://image.tmdb.org/t/p/original/vstpnfQNVyilkmXjmCzfIVwGwjg.jpg', 'The Great Depression hits home for nine year old Kit Kittredge when her dad loses his business and leaves to find work. Oscar nominee Abigail Breslin stars as Kit, leading a splendid cast in the first ever "American Girl" theatrical movie. In order to keep their home, Kit and her mother must take in boarders - paying house - guests who turn out to be full of fascinating stories. When mother''s lockbox containing all their money is stolen, Kit''s new hobo friend Will is the prime suspect. Kit refuses to believe that Will would steal, and her efforts to sniff out the real story get her and friends into big trouble. The police say the robbery was an inside job, committed by someone they know. So if it wasn''t Will, then who did it.', NULL, NULL, 2.6256, 6.472, 0, 1.07, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
