INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12725, 6524, 'tt0102303', NULL, 'Life Stinks', 'Life Stinks', 'movie', 1991, 'https://image.tmdb.org/t/p/w500/uRyxlMbGQwONnN2Ez9ECMPVHxok.jpg', 'https://image.tmdb.org/t/p/original/umDfiTpF5zFzEMfN1rLSorHmS6F.jpg', 'Affluent and arrogant businessman Goddard Bolt, feuding with rival Vance Crasswell over a land deal, makes a bet with Crasswell that he has the wits and street smarts to live penniless and anonymous on the rough streets of Los Angeles for thirty days. But Bolt has a rude awakening when the reality of homelessness hits him. Still, he finds a silver lining in a burgeoning romance with Molly, a former Broadway dancer who has fallen on hard times.', NULL, NULL, 4.0252, 5.634, 0, 1.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12726, 345470, 'tt3917118', NULL, 'Hector', 'Hector', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/6TXtmcu56lte0gv2EsAS4sqOIaZ.jpg', 'https://image.tmdb.org/t/p/original/xm5VK4ugFbYv26pFoK591gYqG4o.jpg', 'Hector has been living on the motorways for years. His once comfortable family life has been replaced by a never-ending tour of service stations that offer him shelter, anonymity, washing facilities and food. The story follows his journey south from Scotland on his annual pilgrimage to a temporary Christmas shelter in London where he finds comfort, friendship and warmth. Over the course of his Homeric journey, Hector decides to reconnect with his long estranged past. As his previous life catches up with him, the story of how he came to be leading a marginal life begins to emerge.', NULL, NULL, 1.1486, 7.161, 0, 1.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
