INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12731, 85827, 'tt0058241', NULL, 'Island of the Blue Dolphins', 'Island of the Blue Dolphins', 'movie', 1964, 'https://image.tmdb.org/t/p/w500/7Cy89UfnqHHaCCkJbNLXYam4Jvk.jpg', 'https://image.tmdb.org/t/p/original/AjjuThMhNF5IgzfpY973aKRT4Tr.jpg', 'Based on the beloved book by Scott O''Dell, this family movie tells the adventures of a young Native American girl. After her father is killed by a malevolent white trapper, Karana joins her community as they leave their island home in the Pacific to live on the mainland. Upon her departure, Karana realizes that her brother has been left behind. She immediately swims back to be with him and the two remain on the abandoned island. Though Karana is able to domesticate a wolf, her brother is not so fortunate with the animals and is killed by a pack of wild dogs. She is left to survive against the odds.', NULL, NULL, 1.0503, 6.5, 0, 1.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
