INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12735, 12797, 'tt0995039', NULL, 'Ghost Town', 'Ghost Town', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/b8VS14DwpLlugTxVWSllYU0Gjn5.jpg', 'https://image.tmdb.org/t/p/original/iDgK5UFgXKVqegWYc5tl58qfGOw.jpg', 'Bertram Pincus, a cranky, people-hating Manhattan dentist, develops the unwelcome ability to see dead people. Really annoying dead people. Even worse, they all want something from him, particularly Frank Herlihy, a smooth-talking ghost, who pesters him into a romantic scheme involving his widow Gwen. They are soon entangled in a hilarious predicament between the now and the hereafter!', NULL, NULL, 4.5109, 6.504, 0, 10.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12736, 269598, 'tt0060260', NULL, 'The Crazy-Quilt', 'The Crazy-Quilt', 'movie', 1966, 'https://image.tmdb.org/t/p/w500/sZZQW6CI0oVrxdOrH73K5soGsi1.jpg', NULL, 'A man with no illusions marries a young woman who is brimming with idealism. She attempts to remake her husband with her overflowing optimism, but the marriage is severely strained when her first pregnancy ends in miscarriage. They separate, and the woman has a number of affairs, but eventually she returns to her husband. They have a daughter, then settle down to a life that is a blend of the husband''s worldliness and the wife''s idealism.', NULL, NULL, 0.8, 5.5, 0, 8.02, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12737, 26333, 'tt0108451', NULL, 'Untamed Heart', 'Untamed Heart', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/2NTqe5MGx5YAXyQuMvwXSevNHeQ.jpg', 'https://image.tmdb.org/t/p/original/dbu06T6Mm3JlSwzLpz2bBfJcqEa.jpg', 'Caroline, a young waitress who seems to have bad taste in men, is on her way home one night when thugs attempt to rape her. Adam, the mysterious busboy who works at the same diner, helps fight off the assailants, and she begins a relationship with him -- but not all their fellow Minnesotans are happy for them. Meanwhile, the couple face their own difficulties when Caroline finds about Adam''s past, including his unique health condition.', NULL, NULL, 3.3881, 6.845, 0, 10.02, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12738, 2172, 'tt0093668', NULL, 'Pathfinder', 'Ofelas', 'movie', 1987, 'https://image.tmdb.org/t/p/w500/cpJvdyNZaD3j2DUHO10Xa7vG8rJ.jpg', 'https://image.tmdb.org/t/p/original/bWoGpYfhHjod5795MpFgH8zMoFj.jpg', 'Around the year 1000 AD warlike people, the so-called "tjuder", roam in northern Scandinavia. As they brutally kill a family in a remote area, including the parents and their little daughter, the family''s teenage son, Aigin, observes the slaughter. He manages to flee from these killers and reaches a camp with other Sámi whose inhabitants are worried if he has been able to hide his track. Afraid of the murderous people, they decide to flee to the coast. The boy stays alone to avenge his family''s murder. Unfortunately, they get him before he can do anything and force him to lead them to the other Sámi. He guides them but has a plan to destroy the barbarous people before reaching the camp.', NULL, NULL, 2.3659, 6.944, 0, 1.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12739, 253307, 'tt2553424', NULL, 'The Infinite Man', 'The Infinite Man', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/tFAHx3bJBE3ZpLpIlYCLSE4eKqQ.jpg', 'https://image.tmdb.org/t/p/original/6FkLR9rpsMviZU7lWRAKgLuG9Zt.jpg', 'A man''s attempts to construct the ultimate romantic weekend backfire when his quest for perfection traps his lover in an infinite loop.', NULL, NULL, 1.1025, 5.992, 0, 1.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12740, 4170, 'tt0840094', NULL, 'Five Days', 'Five Days', 'tv', 2007, 'https://image.tmdb.org/t/p/w500/mnRh1Jcn6KAhgVyfVPDLJwgaOSu.jpg', 'https://image.tmdb.org/t/p/original/d3anTCH5bU5rddJfK0S1GpxTDff.jpg', 'Thriller series which tracks five 24-hour periods in a police investigation.', NULL, NULL, 6.185, 5.8, 0, 1.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12741, 10145, 'tt0356618', NULL, 'The Forgotten', 'The Forgotten', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/gANKh0Vm00CTE1Hf2aTh2IIXn8X.jpg', 'https://image.tmdb.org/t/p/original/tq5xnlYFDlfRZvSAOr3T7H8Yeko.jpg', 'Telly Paretta is a grieving mother struggling to cope with the loss of her 9-year-old son. She is stunned when her psychiatrist reveals that she has created nine years of memories about a son she never had. But when she remembers a man who had a similar experience, Telly embarks on a search to prove her son''s existence, and her sanity.', NULL, NULL, 5.2861, 5.94, 0, 1.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12742, 987573, 'tt21627390', NULL, 'Believers', 'ビリーバーズ', 'movie', 2022, 'https://image.tmdb.org/t/p/w500/o6gF3tCiMwGKM5M9DvgH8sEPXFu.jpg', 'https://image.tmdb.org/t/p/original/nx0tV9PN4uCF8GIBnqjfjrXVYrF.jpg', 'On a small island somewhere near Japan, three cult members have devoted themselves to the "Deserted Island Program". Calling each other by rank, these people-two men and one women-have been chosen by their superiors to throw off the corrupt influence of modern society and "purify" themselves. But as time passes two of the members begin to give into human desire.', NULL, NULL, 5.4153, 5.6, 0, 1.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12743, 517345, 'tt4714962', NULL, 'Blood and Steel: Cedar Crest Country Club', 'Blood and Steel: Cedar Crest Country Club', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/6RneUEKJ127a6jbBQquddrMYPfn.jpg', 'https://image.tmdb.org/t/p/original/fui2tqBbDWc0yyOvBgS8XwpcLqO.jpg', 'In the middle of nowhere lived an unexpected piece of skateboarding and punk music history. "The Crest"..a skateboarding mecca of the 80''s, a veritable metal monolith, tucked away on a country club in the suburbs of the nation''s Capital. It was a place of pure unadulterated expressionist freedom where cutting edge skateboarding and punk rock music collided and made history. Professional skaters and legendary bands, 11 gauge steel and, of course, blood. "Blood and Steel: Cedar Crest Country Club" is the story of a one of a kind skateboarding playground that attracted skaters and bands from all over to come experience what became known simply as, "The Crest".', NULL, NULL, 0.4386, 8.0, 0, 1.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12744, 35648, 'tt0102812', NULL, 'Roujin Z', '老人Z', 'movie', 1991, 'https://image.tmdb.org/t/p/w500/kpJBEfjC9l7BFhmmGPmkNB8gl6h.jpg', 'https://image.tmdb.org/t/p/original/yDLFUmq4ublCJFktG3zpMb3tUfR.jpg', 'Mr. Takazawa, an elderly invalid who is cared for at his home by Haruko, a young nursing student, is chosen by the Japanese Ministry of Public Welfare to test the Z-001, a computerized hospital bed with robotic features that allegedly displays more efficiency and skills than any human nurse, but Haruko mistrusts a machine unable to consider human feelings.', NULL, NULL, 4.0582, 6.647, 0, 1.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12745, 84329, 'tt1990314', NULL, 'Robot & Frank', 'Robot & Frank', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/602vUwe1GPmaRvcrT3OQWqH1Nm1.jpg', 'https://image.tmdb.org/t/p/original/mV2UZZHYiWPKH0AwtMSil1T7DUH.jpg', 'Curmudgeonly old Frank lives by himself. His routine involves daily visits to his local library, where he has a twinkle in his eye for the librarian. His grown children are concerned about their father’s well-being and buy him a caretaker robot. Initially resistant to the idea, Frank soon appreciates the benefits of robotic support – like nutritious meals and a clean house – and eventually begins to treat his robot like a true companion. With his robot’s assistance, Frank’s passion for his old, unlawful profession is reignited, for better or worse.', NULL, NULL, 3.6802, 6.899, 0, 1.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12746, 33423, 'tt0037248', NULL, 'The Scarlet Claw', 'The Scarlet Claw', 'movie', 1944, 'https://image.tmdb.org/t/p/w500/1laSfU5KqQjwgxRqyTUuSmTZIZe.jpg', 'https://image.tmdb.org/t/p/original/hyZCJs9D97GnM7mCWF7CM1LH28T.jpg', 'When a woman is found dead with her throat torn out, the local villagers blame a supernatural monster. But Sherlock Holmes, who gets drawn into the case from nearby Quebec, suspects a human murderer.', NULL, NULL, 1.9993, 6.934, 0, 1.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12747, 27883, 'tt0040558', NULL, 'Macbeth', 'Macbeth', 'movie', 1948, 'https://image.tmdb.org/t/p/w500/4DbzuePqGcUY7olAKzGly7kCEmU.jpg', 'https://image.tmdb.org/t/p/original/jyTQJ1ioXoWs7zBrAJy9w4AHZyZ.jpg', 'Macbeth, the Thane of Glamis, receives a prophecy from a trio of witches that one day he will become King of Scotland. Consumed by ambition and spurred to action by his wife, Macbeth commits a treasonous act and takes the throne for himself.', NULL, NULL, 3.0363, 7.263, 0, 1.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
