INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12749, 115494, 'tt0055626', NULL, 'The Young Ones', 'The Young Ones', 'movie', 1961, 'https://image.tmdb.org/t/p/w500/bVceeDimc6g2NsQpdzC82GB3Qy1.jpg', 'https://image.tmdb.org/t/p/original/5xP6ZHSk4x2tBO7t8z2qStBf4y0.jpg', 'Nicky and his friends find that their youth club is in danger of being flattened to make way for a new office block unless they can come up with £1500 to pay the new owner, the ruthless property tycoon Hamilton Black. To help raise the cash, Nicky records a song and his friends broadcast it via a pirate radio station, touting him as "The Mystery Singer" - the plan works and interest in their up and coming show is heightened by this new but unknown heart-throb. But Nicky has an even bigger secret and one that he cannot share, even with his girlfriend Toni... Hamilton Black is his father.', NULL, NULL, 1.2805, 6.1, 0, 10.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12750, 9450, 'tt0115744', NULL, 'Brassed Off', 'Brassed Off', 'movie', 1996, 'https://image.tmdb.org/t/p/w500/qS2cZYWn2jlQs4Ej5O42LVIANQB.jpg', 'https://image.tmdb.org/t/p/original/c8Ooqu8owDRo2iK7LYCvdZuUaV9.jpg', 'A Yorkshire coal mine is threatened with closure and the only hope is for the men to enter their Grimley Colliery Brass Band into a national competition. They believe they have no hope until Gloria appears carrying her Flugelhorn. At first mocked for being a woman, she soon becomes the only chance for the band to win.', NULL, NULL, 2.8757, 6.988, 0, 10.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12751, 12407, 'tt1037156', NULL, 'Stone of Destiny', 'Stone of Destiny', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/rZWhnQY4Efi0iYQpnagP4vyaYps.jpg', 'https://image.tmdb.org/t/p/original/aRTPt9ZK8oKlolgLZzlMm8UDvop.jpg', 'Tells of the daring heist of The Stone of Destiny in the 1950s by a charming group of idealistic Scottish undergraduates, whose action rekindled Scottish nationalistic pride.', NULL, NULL, 1.4497, 6.5, 0, 10.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12752, 38344, 'tt0410400', NULL, 'On a Clear Day', 'On a Clear Day', 'movie', 2005, 'https://image.tmdb.org/t/p/w500/gE2TRj270Z4KJ5tjSnhpROBwxIH.jpg', 'https://image.tmdb.org/t/p/original/fJeWzL72YMMXZJ7DA0DTu73DOTZ.jpg', 'After decades of laboring as a Glasgow shipbuilder, Frank Redmond, a no-nonsense 55-year-old working-class man, suddenly finds himself laid off. For the first time in his life, he is without a job or a sense of direction, and he''s too proud to ask for guidance. His best mates - rascally Danny, timid Norman and cynical Eddie - are there for him, but Frank still feels desperately alone. An offhand remark from Danny inspires Frank to challenge himself. Already contemplating the state of his relationships with loving wife Joan and all-but-estranged son Rob, Frank is determined to shore up his own self-confidence. He will attempt the near impossible - swimming the English Channel.', NULL, NULL, 1.8613, 6.4, 0, 10.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12753, 22908, 'tt0202559', NULL, 'A Room for Romeo Brass', 'A Room for Romeo Brass', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/gLpv2UUf5We4sXDKdo11aFfnKgw.jpg', 'https://image.tmdb.org/t/p/original/uztdTUkWckVTrjQLWPE5YOttbxY.jpg', 'Two twelve-year-old boys, Romeo and Gavin, undergo an extraordinary test of character and friendship when Morell, a naive but eccentric and dangerous stranger, comes between them. Morell befriends with the two boys and later asks them to help him pursue Romeo''s beautiful elder sister. He gradually becomes more violent after she rejects him.', NULL, NULL, 1.1785, 6.97, 0, 9.51, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
