INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12767, 1437511, 'tt35866986', NULL, 'How to Rob a Bank', 'How to Rob a Bank', 'movie', 2026, 'https://image.tmdb.org/t/p/w500/8sMzu56Nok5WlEXCRdflEgshYQO.jpg', 'https://image.tmdb.org/t/p/original/xghtLO90cQPybH85aw1C3bZ2P3.jpg', 'A crew of social media-savvy bank robbers broadcasts their daring heists, unaware that their growing viral fame has put them in the crosshairs of a veteran FBI agent and a brilliant software engineer. Despite the unlikely duo closing in, the crime ring pushes past their limits, putting everything on the line for their most ambitious heist yet.', NULL, NULL, 5.4835, 0.0, 0, 9.51, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12768, NULL, NULL, 1003, 'Enter the Matrix', 'Enter the Matrix', 'game', 2003, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1oum.jpg', NULL, 'Enter the Matrix is the first video game based on The Matrix series of films. Its story was concurrent with that of The Matrix Reloaded, and featured over an hour of original footage, directed by The Wachowskis and starring the cast of the film trilogy, produced exclusively for the game. It sold one million copies in its first eighteen days of release, 2.5 million over the first six weeks, and ultimately 5 million copies.

First released in May 2003, the same month as The Matrix Reloaded, Enter the Matrix was simultaneously produced with The Matrix Reloaded and The Matrix Revolutions. It was developed by Shiny Entertainment, published by Atari and distributed by Warner Bros. Interactive Entertainment for the GameCube, Microsoft Windows, PlayStation 2 and Xbox.', 'https://www.igdb.com/games/enter-the-matrix', '["Xbox", "Nintendo GameCube", "PC (Microsoft Windows)", "PlayStation 2"]', NULL, NULL, 0, 1.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12769, 153272, 'tt0117865', NULL, 'Taxandria', 'Taxandria', 'movie', 1996, 'https://image.tmdb.org/t/p/w500/gU0eypUcxcoFaqoZwMrFuXVylb0.jpg', 'https://image.tmdb.org/t/p/original/81mTaTJzYTQEq5Zm5J8tZil7ZlF.jpg', 'A lighthouse guardian leads a young prince towards an imaginary world, Taxandria, where the boy learns about the power of love and the value of liberty. A totalitarian regime has forbidden time: time watches have been confiscated, photo cameras are illegal as they freeze a point in time. A typical Servais theme: a power is oppressed by a constraint that denies what is best in the individual, and therefore has to be twisted in various ways, to establish an entirely artificial world, that has rules that may question some of the rules of our world at this side of the mirror.', NULL, NULL, 0.9054, 5.938, 0, 8.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12770, 3868, 'tt0830361', NULL, 'The Lost Room', 'The Lost Room', 'tv', 2006, 'https://image.tmdb.org/t/p/w500/ixfo1ysvboBxYehdDDC9D0T3Q33.jpg', 'https://image.tmdb.org/t/p/original/jVshEAWP068E4tp4ewjIHFKB7Iz.jpg', 'A detective investigates a mysterious motel room, which acts as a portal to an alternate universe.', NULL, NULL, 6.6911, 7.75, 0, 9.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12771, 65733, 'tt4083422', NULL, 'Doraemon', 'ドラえもん', 'tv', 2005, 'https://image.tmdb.org/t/p/w500/9ZN1P32SHviL3SV51qLivxycvcx.jpg', 'https://image.tmdb.org/t/p/original/c2oiRa7V3bQzof4wVGzLXtWJ5QU.jpg', 'Robotic cat Doraemon is sent back in time from the 22nd century to protect 10-year-old Noby, a lazy and uncoordinated boy who is destined to have a tragic future. Doraemon can create secret gadgets from a pocket on his stomach, but they usually cause more bad than good because of Noby''s propensity to misuse them.', NULL, NULL, 127.1496, 8.1, 0, 7.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
