INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12780, 28308, 'tt0201485', NULL, 'The Body', 'The Body', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/lCTA1B2oFev0bcXVZZuh93qDjix.jpg', 'https://image.tmdb.org/t/p/original/wytfOgPzYnYUqEbXUyM38HIcYXP.jpg', 'An ancient skeleton has been discovered in Jerusalem in a rich man''s tomb. Colouration of the wrist and leg bones indicates the cause of death was crucifiction. other signs, include a gold coin bearing the marks of Pontius Pilate and faint markings around the skull, lead authorities to suspect that these could be the bones of Jesus Christ. Politicians, clerics, religious extremists and those using terror as a means to an end, find their beliefs and identities tested while risking their lives to unearth the truth.....', NULL, NULL, 3.8416, 5.525, 0, 1.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
