INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12782, 37632, 'tt0193364', NULL, 'The Order', 'The Order', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/xcs2taqwgKu2tDrcXd2k7XbtmLq.jpg', 'https://image.tmdb.org/t/p/original/xUHUfugurdPJCIO33g6TFSEeK3c.jpg', 'When Rudy, an artifacts smuggler, goes to Jerusalem to rescue his kidnapped archeologist father, he faces deportation by a scheming police chief. Now, to find his dad and recover a sacred scroll, he''ll have to outwit officials and a ruthless sect. With the help of a beautiful Israeli cop, Rudy battles a faction of religious zealots determined to see a holy war at all costs.', NULL, NULL, 4.2852, 5.112, 0, 1.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
