INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12784, 62120, 'tt3597606', NULL, 'Dig', 'Dig', 'tv', 2015, 'https://image.tmdb.org/t/p/w500/uBv3pEpjgklfirbLhGS0GOJWHbe.jpg', 'https://image.tmdb.org/t/p/original/rfpdvpBpkYThUwIFPjSFB6QkVyk.jpg', 'When FBI Agent Peter Connelly, recently stationed in Jerusalem, begins investigating the murder of a young American, he realizes that he’s uncovered an ancient international conspiracy that threatens to change the course of human history. Certain that the dangerous prophecy is nearing fruition, Peter must race against the clock to unravel its mystery. From a remote farm in Norway, to an enigmatic compound in New Mexico, to the serpentine tunnels of Jerusalem, he searches for the truth, the revelation of which will shake the world''s beliefs to its very core.', NULL, NULL, 4.2601, 6.261, 0, 1.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
