INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12792, 36994, 'tt0195274', NULL, 'Sun, Hay, Strawberries', 'Slunce, seno, jahody', 'movie', 1984, 'https://image.tmdb.org/t/p/w500/xmQvdloN2a7RmG2hAhPDYFYuvk0.jpg', 'https://image.tmdb.org/t/p/original/m8igxLkPDJuNTTibnpnhnYXS85q.jpg', 'A Czech agricultural student, Šimon Plánička, arrives at the small South Bohemian town of Hoštice, and joins the local JZD (agricultural co-op) with the intention of trying out his experiment regarding the "Milk yield of cows in regards to a cultured environment". He runs into difficulty with the directorship of the JZD, but he finds them eager to help once they hear he''s the son of the local agricultural commissioner, as his last name is also Plánička. Blažena Škopková is given the task of finding out how things are looking. However everything is complicated by the jealousy of Blažena''s boyfriend Venca.', NULL, NULL, 0.9021, 6.987, 0, 11.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
