INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12803, 75506, 'tt0049964', NULL, 'World Without End', 'World Without End', 'movie', 1956, 'https://image.tmdb.org/t/p/w500/flvqHHFMBCks5Mlb4HWydUZcwbV.jpg', 'https://image.tmdb.org/t/p/original/fJevLurT8xaEpVtDjzD1Uyk8sdW.jpg', 'Four astronauts returning from man''s first mission to Mars enter a time warp and crash on a 26th-century Earth devastated by atomic war.  At first unaware where they are, but finding the atmosphere safe to breathe, they start exploring and find themselves in a divided future where disfigured mutants living like cavemen inhabit the surface, while the normals live comfortably below the surface but are dying as a race from lack of natural water, air and sunlight.', NULL, NULL, 1.8049, 5.717, 0, 1.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12804, 29347, 'tt0050393', NULL, 'Fiend Without a Face', 'Fiend Without a Face', 'movie', 1958, 'https://image.tmdb.org/t/p/w500/mvy9fNmdFIMlStKVFWUvMP8JpNX.jpg', 'https://image.tmdb.org/t/p/original/3PedPRnQUuB4XCaVmCWv2nHrmBA.jpg', 'An American airbase in Canada provokes resentment from the nearby residents after fallout from nuclear experiments at the base are blamed for a recent spate of disappearances. A captain from the airbase is assigned to investigate, and begins to suspect that an elderly British scientist who lives near the base and conducts research in the field of mind over matter knows more than he is letting on..', NULL, NULL, 1.4138, 6.06, 0, 1.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12805, 107380, 'tt0138363', NULL, 'Cigarettes & Coffee', 'Cigarettes & Coffee', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/coz58zPNbVDLbm6r6n7IdppgwUX.jpg', 'https://image.tmdb.org/t/p/original/enJ15o96yf4HHhQ8R47IB1IrPL5.jpg', 'At a desert diner, the lives of five strangers become linked through a single twenty-dollar bill. Shot for $20,000 and starring Philip Baker Hall, the short premiered at Sundance and later inspired Anderson’s debut feature Hard Eight (1996).', NULL, NULL, 1.7377, 6.6, 0, 1.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12806, 381064, 'tt4671002', NULL, 'American Fable', 'American Fable', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/5D1dsGCh09cJlla924hnVYror6z.jpg', 'https://image.tmdb.org/t/p/original/j0gs2ROuekTCy9X4oSfYxbOZ6by.jpg', 'When 11-year-old Gitty discovers that her father, Abe, a good and beloved farmer, is holding a wealthy man hostage in their abandoned silo in order to save their suffering farm, she befriends the captive in secret. As the truth unfolds about who he is and what will happen if he escapes, Gitty chooses to confront the thin line between reality and fiction.', NULL, NULL, 1.3956, 6.054, 0, 1.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
