INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12816, 29114, 'tt0076665', NULL, 'Satan''s Cheerleaders', 'Satan''s Cheerleaders', 'movie', 1977, 'https://image.tmdb.org/t/p/w500/fJ1pXNo6bjGZdO5vWY7gIxg8A7C.jpg', 'https://image.tmdb.org/t/p/original/kZdW5RCKHVTyfYhcfpkWFhQimXU.jpg', 'The janitor at a local high school is actually the scout for a coven of Satanists on the lookout for a virgin to sacrifice. One day he kidnaps the cheerleading squad to use for their rituals. However, unbeknownst to the devil-worshipers, one of the cheerleaders is actually a witch, and has plans of her own for the Satanists.', NULL, NULL, 1.5597, 4.473, 0, 1.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
