INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12818, 9454, 'tt0120631', NULL, 'EverAfter', 'EverAfter', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/9TspO5dThMBioF0DFrvy6YqrngH.jpg', 'https://image.tmdb.org/t/p/original/lhpokM60CnLWcNETQqKMz2q9ryL.jpg', 'Danielle, a vibrant young woman, was forced into servitude after the death of her father when she was a young girl. Danielle''s stepmother, Rodmilla, is a heartless woman who forces Danielle to do the cooking and cleaning, while she tries to marry off the eldest of her two daughters to the prince. But Danielle''s life takes a wonderful turn when, under the guise of a visiting royal, she meets the charming Prince Henry.', NULL, NULL, 5.9039, 7.451, 0, 1.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12819, 118266, 'tt0338018', NULL, 'The Fabulous Adventures of the Legendary Baron Munchausen', 'Les Fabuleuses Aventures du légendaire baron de Münchausen', 'movie', 1979, 'https://image.tmdb.org/t/p/w500/qgUlWPxCFMvhy3Jtbw5gjImUSmV.jpg', 'https://image.tmdb.org/t/p/original/kVAHjIxnBKHkxDh1FKdtRjNWiab.jpg', 'The Fabulous Adventures of the legendary Baron Munchausen is a French animated feature from Jean Image of 1978, inspired by the adventures of Baron Munchausen. Baron Munchausen is wont to bring his friends to tell them about his imaginary exploits.', NULL, NULL, 0.8538, 6.5, 0, 1.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12820, 1534922, 'tt37997046', NULL, 'W : A Return to Oz', 'W : A Return to Oz', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/rkMMFlWXOrc99S6nyixHmGsBdDd.jpg', 'https://image.tmdb.org/t/p/original/2khlhPQT9D9sokWGhytX7OghS0Z.jpg', 'Witness the rise and fall of The Warehouse, a rave venue from Plymouth and times gone by now reduced to a derelict shell. We explore its history, its people and the future. An amateur filmmaker-explorer finds the building in an empty derelict state, long after the prosperous life and energy it endured through the 90s. Through a combination of archives and stories of people who lived there, the film explores through the medium of analogue what once was and how even a now silent derelict shell can become the centre of the universe.', NULL, NULL, 0.7215, 0.0, 0, 1.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
