INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12824, 135934, 'tt11247158', NULL, 'The Legend of Vox Machina', 'The Legend of Vox Machina', 'tv', 2022, 'https://image.tmdb.org/t/p/w500/zjQTSYZEmy0GVnK1aFLvNiAwluo.jpg', 'https://image.tmdb.org/t/p/original/qCGwPCwlSiLdlYinzy9rSQDjQX1.jpg', 'They''re rowdy, they''re ragtag, they''re misfits turned mercenaries for hire. Vox Machina is more interested in easy money and cheap ale than actually protecting the realm. But when the kingdom is threatened by evil, this boisterous crew realizes that they are the only ones capable of restoring justice.', NULL, NULL, 33.6874, 8.221, 0, 1.01, '2026-08-30 03:38:44', '2026-08-30 03:38:44');
