UPDATE "recommendations" SET "tmdb_id"=6114, "imdb_id"='tt0103874', "igdb_id"=NULL, "title"='Bram Stoker''s Dracula', "original_title"='Bram Stoker''s Dracula', "media_type"='movie', "release_year"=1992, "poster_url"='https://image.tmdb.org/t/p/w500/jSxCIZXudp5q8wQO8VERGX8hRAl.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/88S6EYQBVyQktDfSqsB33I169jN.jpg', "overview"='Count Dracula, a 15th-century prince, is condemned to live off the blood of the living for eternity. Young lawyer Jonathan Harker is sent to Dracula''s castle to finalise a land deal, but when the Count sees a photo of Harker''s fiancée, Mina, the spitting image of his dead wife, he imprisons him and sets off for London to track her down.', "external_url"=NULL, "platforms"=NULL, "popularity"=12.7246, "vote_average"=7.4, "is_ambiguous"=0, "evidence_score"=67.65765625, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-30 03:38:44' WHERE "id"=1;
UPDATE "recommendations" SET "tmdb_id"=120, "imdb_id"='tt0120737', "igdb_id"=NULL, "title"='The Lord of the Rings: The Fellowship of the Ring', "original_title"='The Lord of the Rings: The Fellowship of the Ring', "media_type"='movie', "release_year"=2001, "poster_url"='https://image.tmdb.org/t/p/w500/6oom5QYQ2yQTMJIbnvbkBL9cHo6.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/mWDdRXTivGE7aaY2vo1Ie0PfCX5.jpg', "overview"='Young hobbit Frodo Baggins, after inheriting a mysterious ring from his uncle Bilbo, must leave his home in order to keep it from falling into the hands of its evil creator. Along the way, a fellowship is formed to protect the ringbearer and make sure that the ring arrives at its final destination: Mt. Doom, the only place where it can be destroyed.', "external_url"=NULL, "platforms"=NULL, "popularity"=47.6819, "vote_average"=8.439, "is_ambiguous"=0, "evidence_score"=7.87183783783783752e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-30 03:38:44' WHERE "id"=5;
UPDATE "recommendations" SET "tmdb_id"=374052, "imdb_id"='tt3908142', "igdb_id"=NULL, "title"='The Love Witch', "original_title"='The Love Witch', "media_type"='movie', "release_year"=2016, "poster_url"='https://image.tmdb.org/t/p/w500/q6mZjCwGn9KCTrStTRM88pui0is.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/zPzJ3DAUjpJoiBm4jODt50QEEr3.jpg', "overview"='A modern-day witch uses spells and magic to get men to fall in love with her, with deadly consequences.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.6408, "vote_average"=6.435, "is_ambiguous"=0, "evidence_score"=9.23086516853932579e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-30 03:38:44' WHERE "id"=6;
UPDATE "recommendations" SET "tmdb_id"=361292, "imdb_id"='tt1034415', "igdb_id"=NULL, "title"='Suspiria', "original_title"='Suspiria', "media_type"='movie', "release_year"=2018, "poster_url"='https://image.tmdb.org/t/p/w500/bRpKFPb8CWKRQxVo9NzOuPPlO3Q.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/k4renoGJzagylgBYWbpjQLYGAfB.jpg', "overview"='A darkness swirls at the center of a world-renowned dance company, one that will engulf the artistic director, an ambitious young dancer, and a grieving psychotherapist. Some will succumb to the nightmare. Others will finally wake up.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.6076, "vote_average"=6.896, "is_ambiguous"=0, "evidence_score"=4.10607894736842098e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-30 03:38:44' WHERE "id"=8;
