UPDATE "recommendations" SET "tmdb_id"=548473, "imdb_id"='tt5073642', "igdb_id"=NULL, "title"='Color Out of Space', "original_title"='Color Out of Space', "media_type"='movie', "release_year"=2020, "poster_url"='https://image.tmdb.org/t/p/w500/k7rD7LzlsPS4jmE6Siah0QO4tAc.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/vj2gCvD5vZDJ865izTU0J0wJBVc.jpg', "overview"='The Gardner family moves to a remote farmstead in rural New England to escape the hustle of the 21st century. They are busy adapting to their new life when a meteorite crashes into their front yard, melts into the earth, and infects both the land and the properties of space-time with a strange, otherworldly colour. To their horror, the family discovers this alien force is gradually mutating every life form that it touches—including them.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.8805, "vote_average"=6.08, "is_ambiguous"=0, "evidence_score"=4.62516666666666651e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-30 03:38:44' WHERE "id"=1190;
