UPDATE "recommendations" SET "tmdb_id"=1949, "imdb_id"='tt0443706', "igdb_id"=NULL, "title"='Zodiac', "original_title"='Zodiac', "media_type"='movie', "release_year"=2007, "poster_url"='https://image.tmdb.org/t/p/w500/6YmeO4pB7XTh8P8F960O1uA14JO.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/3zCPI4JFc54xvLaJ71oI2KoP3az.jpg', "overview"='Over the course of a decade, editors of the San Francisco Chronicle entice themselves in the murders of the Zodiac Killer. However, as time runs its course, interest in the case dwindles in the eyes of the professionals. The Killer stops interacting with the public. However, believing he has the answers, an amateur cartoonist from the initial sightings races against time to prevent what he believes is another murder.', "external_url"=NULL, "platforms"=NULL, "popularity"=11.2116, "vote_average"=7.533, "is_ambiguous"=0, "evidence_score"=6.53333333333333286e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-30 03:38:44' WHERE "id"=1910;
