UPDATE "recommendations" SET "tmdb_id"=2742, "imdb_id"='tt0102511', "igdb_id"=NULL, "title"='Naked Lunch', "original_title"='Naked Lunch', "media_type"='movie', "release_year"=1991, "poster_url"='https://image.tmdb.org/t/p/w500/u01kh5jKUWjhom76mguRqUgdvja.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/mBteXONDhdVyXRNxj54eMNGNqyT.jpg', "overview"='Blank-faced bug killer Bill Lee and his dead-eyed wife, Joan, like to get high on Bill''s pest poisons while lounging with Beat poet pals. After meeting the devilish Dr. Benway, Bill gets a drug made from a centipede. Upon indulging, he accidentally kills Joan, takes orders from his typewriter-turned-cockroach, ends up in a constantly mutating Mediterranean city and learns that his hip friends have published his work -- which he doesn''t remember writing.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.0439, "vote_average"=6.997, "is_ambiguous"=0, "evidence_score"=4.30547368421052638e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-30 03:38:44' WHERE "id"=1931;
