UPDATE "recommendations" SET "tmdb_id"=682909, "imdb_id"='tt9027796', "igdb_id"=NULL, "title"='Tenebrae', "original_title"='Tenebrae', "media_type"='movie', "release_year"=2018, "poster_url"='https://image.tmdb.org/t/p/w500/w051WuOtyuYG7oGLAtlbklfKQON.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/ra9QoASTrbLmj1MfsA3FtlwT8di.jpg', "overview"='On the last day for the residents to vacate a high-rise apartment before its demolishment, a young girl, Iris, and her mother are moving out. On a tight deadline, her boyfriend and his friend are also present to help. Iris inevitably gets distracted exploring the vacant spaces of her neighbours, relishing the moment. As they pull away in the rental truck for the last time, Iris sits in the back with her boyfriend, surrounded by her furniture. She allows a small ray of light to penetrate the darkness of the truck. The images of the outside world appear on the interior of the truck; they watch the inverted building before it eventually disappears forever.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.4285, "vote_average"=0.0, "is_ambiguous"=0, "evidence_score"=2.01, "created_at"='2026-07-29 20:51:09', "updated_at"='2026-08-30 03:38:44' WHERE "id"=5076;
