UPDATE "recommendations" SET "tmdb_id"=15477, "imdb_id"='tt0110395', "igdb_id"=NULL, "title"='Love and a .45', "original_title"='Love and a .45', "media_type"='movie', "release_year"=1994, "poster_url"='https://image.tmdb.org/t/p/w500/xz7rXuL1lkc6tkt1rS0N05rxtRX.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/5edOoD7mdBrHm2LWeZQIQHiFOrF.jpg', "overview"='Small-time criminal Watty Watts attempts to rob a convenience store with his drug-addict buddy, Billy Mack Black. The robbery, however, leads to murder, and soon Watty leaves Billy behind and goes on the run with his beloved girlfriend, Starlene. Heading toward Mexico, the fugitive couple gets plenty of media coverage, until there are even more people on their trail. Can Watty and Starlene make it south of the border without getting caught?', "external_url"=NULL, "platforms"=NULL, "popularity"=1.7513, "vote_average"=5.733, "is_ambiguous"=0, "evidence_score"=6.84399999999999941e+00, "created_at"='2026-07-29 20:51:09', "updated_at"='2026-08-30 03:38:44' WHERE "id"=5443;
UPDATE "recommendations" SET "tmdb_id"=84175, "imdb_id"='tt2125435', "igdb_id"=NULL, "title"='Beasts of the Southern Wild', "original_title"='Beasts of the Southern Wild', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/nQJmWekGYlXhezGUb21xFfEfwhH.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/7LWLPvyfLSb2oOlgWwAwUqA8uKo.jpg', "overview"='Hushpuppy, an intrepid six-year-old girl, lives with her father, Wink, in ''the Bathtub'', a southern Delta community at the edge of the world. Wink’s tough love prepares her for the unraveling of the universe—for a time when he’s no longer there to protect her. When Wink contracts a mysterious illness, nature flies out of whack—temperatures rise and the ice caps melt, unleashing an army of prehistoric creatures called aurochs. With the waters rising, the aurochs coming, and Wink’s health fading, Hushpuppy goes in search of her lost mother.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.2017, "vote_average"=6.841, "is_ambiguous"=0, "evidence_score"=23.561875, "created_at"='2026-07-29 20:51:09', "updated_at"='2026-08-30 03:38:44' WHERE "id"=5468;
