UPDATE "recommendations" SET "tmdb_id"=12632, "imdb_id"='tt0110246', "igdb_id"=NULL, "title"='Kaspar Hauser', "original_title"='Kaspar Hauser', "media_type"='movie', "release_year"=1993, "poster_url"='https://image.tmdb.org/t/p/w500/7gA2f8X9bim0905iC5NMXCJh7OS.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/u56QuOLIWxcbTaZNUwiir3Q6NPY.jpg', "overview"='In May 1828, a feral boy aged around 16 was found in Nuremberg. Kaspar Hauser, as he is called, can only speak a few indistinct words and knows nothing about his origins or family. The film depicts the - presumed - circumstances under which Hauser was held captive in complete isolation in a hiding place from infancy onwards. From this emerges the picture of an intrigue involving high circles of aristocratic society. Five years after his liberation, in December 1833, Kaspar Hauser died as a result of a stab wound inflicted by an unknown perpetrator.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.4638, "vote_average"=6.188, "is_ambiguous"=0, "evidence_score"=10.51, "created_at"='2026-08-18 01:44:45', "updated_at"='2026-08-30 03:38:44' WHERE "id"=10342;
