UPDATE "recommendations" SET "tmdb_id"=1462635, "imdb_id"=NULL, "igdb_id"=NULL, "title"='Angela', "original_title"='Angela', "media_type"='movie', "release_year"=NULL, "poster_url"=NULL, "backdrop_url"=NULL, "overview"='Angela Morgan lives a picture-perfect life—successful career, beautiful home, loving husband. But behind the calm surface lies a storm of repressed memories and unanswered questions. When she begins experiencing vivid nightmares and cryptic hallucinations, Angela sets out on a journey to uncover the truth about her past.  As she digs deeper, a forgotten childhood trauma resurfaces, tied to a mysterious woman who once lived next door. Reality begins to blur as Angela is pulled into a web of deception, obsession, and psychological manipulation.  With time running out and her sanity unraveling, Angela must confront the haunting secrets buried in her mind before they destroy everything she’s built.', "external_url"=NULL, "platforms"=NULL, "popularity"=0.3708, "vote_average"=0.0, "is_ambiguous"=0, "evidence_score"=3.01333333333333319e+00, "created_at"='2026-08-19 01:49:52', "updated_at"='2026-08-30 03:38:44' WHERE "id"=10485;
