UPDATE "recommendations" SET "tmdb_id"=14801, "imdb_id"='tt0064177', "igdb_id"=NULL, "title"='Colossus: The Forbin Project', "original_title"='Colossus: The Forbin Project', "media_type"='movie', "release_year"=1970, "poster_url"='https://image.tmdb.org/t/p/w500/kmVDlTzERxSvBrqtQurjKf1zEy1.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/3eV9l3HhOGOytCilHJOACDL9DIT.jpg', "overview"='The U.S. has handed over control of its nuclear defense system to the Colossus supercomputer designed by scientist Dr. Charles Forbin. It soon becomes clear, that the now-sentient Colossus is far more intelligent than its creator realized—with the fate of the world hanging in the balance.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.9505, "vote_average"=6.966, "is_ambiguous"=0, "evidence_score"=5.765, "created_at"='2026-08-19 01:49:52', "updated_at"='2026-08-30 03:38:44' WHERE "id"=10657;
