UPDATE "recommendations" SET "tmdb_id"=82690, "imdb_id"='tt1772341', "igdb_id"=NULL, "title"='Wreck-It Ralph', "original_title"='Wreck-It Ralph', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/nrEupcBwf4O1zihCM34NoXusZDq.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/3IFRjBDwtk0DlIsDfJ2zEzLjUBi.jpg', "overview"='Wreck-It Ralph is the 9-foot-tall, 643-pound villain of an arcade video game named Fix-It Felix Jr., in which the game''s titular hero fixes buildings that Ralph destroys. Wanting to prove he can be a good guy and not just a villain, Ralph escapes his game and lands in Hero''s Duty, a first-person shooter where he helps the game''s hero battle against alien invaders. He later enters Sugar Rush, a kart racing game set on tracks made of candies, cookies and other sweets. There, Ralph meets Vanellope von Schweetz who has learned that her game is faced with a dire threat that could affect the entire arcade, and one that Ralph may have inadvertently started.', "external_url"=NULL, "platforms"=NULL, "popularity"=16.5804, "vote_average"=7.361, "is_ambiguous"=0, "evidence_score"=4.0475, "created_at"='2026-08-20 01:43:50', "updated_at"='2026-08-30 03:38:44' WHERE "id"=10692;
